scripts.script:
local b = Instance.new("BindableFunction")
b.OnInvoke = function(ans)
    if ans == "Manual" then
        loadstring(game:HttpGet("https://raw.githubusercontent.com/gumanba/Scripts/refs/heads/main/DeadRails"))()
    else
        loadstring(game:HttpGet("https://raw.githubusercontent.com/gumanba/Scripts/refs/heads/main/DeadRailsAuto"))()
    end
end
game.StarterGui:SetCore("SendNotification", {
	Title = "Automatic or manual farm?";
	Text = "Click a button";
	Duration = "5";
	Button1 = "Manual";
	Button2 = "Auto";
	Callback = b
})
